import 'package:flutter/material.dart';void main() {  runApp(const MyApp());}class MyApp extends StatelessWidget {  const MyApp({super.key});  @override  Widget build(BuildContext context) {    return const MaterialApp(      title: 'Simple Calculator',      home: CalculatorPage(),    );  }}class CalculatorPage extends StatefulWidget {  const CalculatorPage({super.key});  @override  State<CalculatorPage> createState() => _CalculatorPageState();}class _CalculatorPageState extends State<CalculatorPage> {  final _controller = TextEditingController();  double? _result;  void _calculate() {    try {      _result = _calculateExpression(_controller.text);      setState(() {});    } catch (e) {      _result = null;      setState(() {});    }  }  double _calculateExpression(String expression) {    return eval(expression);  }  double eval(final String expression) {    return double.parse(expression);  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text('Simple Calculator'),      ),      body: Padding(        padding: const EdgeInsets.all(16.0),        child: Column(          mainAxisAlignment: MainAxisAlignment.spaceBetween,          children: [            TextField(              controller: _controller,              decoration: const InputDecoration(                border: OutlineInputBorder(),                hintText: 'Enter expression',              ),            ),            ElevatedButton(              onPressed: _calculate,              child: const Text('Calculate'),            ),            Text(              _result != null                  ? 'Result: $_result'                  : 'Enter an expression and press Calculate',            ),          ],        ),      ),    );  }}